(()=>{'use strict';const V='20260728-team-fast-v1';const root=document.getElementById('team-page-root');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');const num=v=>Number(v)||0;const format=v=>num(v).toLocaleString('pt-BR');const slug=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');const aliases={'loud':'loud-snickers','fluxo':'fluxo-w7m','afg':'afrogames','a7':'alpha7','sxgaming':'sx-tet','sxtet':'sx-tet','cptvox':'cpt-vox','influencerage':'influence-rage','rise':'rise-gaming','rush':'rush-gaming','solid':'team-solid'};async function json(url){const r=await fetch(url,{cache:'default'});if(!r.ok)throw new Error('Falha ao carregar os dados');return r.json()}function findTeam(teams,query){const key=norm(query),mapped=aliases[key];return teams.find(t=>norm(t.name)===key||norm(t.abbreviation)===key||slug(t.name)===query||slug(t.name)===mapped)||teams.find(t=>slug(t.name)===mapped)||null}function role(p){const r=String(p?.currentRoster?.roleShort||p?.currentRoster?.role||p?.role||'').toUpperCase();return r==='GRAN'?'Granadeiro':r==='SUP'?'Suporte':r==='3'?'3º homem':r==='RUSH'?'Rush':r||'Função não informada'}function photo(p){return window.cffResolvePlayerPhoto?.(p?.name,p?.photo)||p?.photo||'silhueta.webp'}function playerStats(p,stats){const candidates=[p.id,p.name,...(p.aliases||[])].map(norm);const hit=Object.entries(stats||{}).find(([k,v])=>candidates.includes(norm(k))||candidates.includes(norm(v?.name)));return hit?.[1]||p.s2||{}}function teamRow(stages,name){const rows=['classificatoria','segundaFase','final'].flatMap(k=>Array.isArray(stages?.[k]?.rows)?stages[k].rows:[]);return rows.find(r=>norm(r.team||r.equipe||r.name)===norm(name))||{}}function tags(p){const r=p.currentRoster||{};return[(r.captain?'<span class="cff-player-tag captain">Capitão</span>':''),(r.rookie?'<span class="cff-player-tag rookie">Estreante</span>':''),(!r.starter?'<span class="cff-player-tag">Reserva</span>':'')].join('')}function card(p,stats,logo){const s=playerStats(p,stats),r=p.currentRoster||{},avg=num(s.matches)?(num(s.kills)/num(s.matches)).toFixed(2):'0.00';return `<a class="cff-player-card${r.starter===false?' is-reserve':''}" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}"><div class="cff-player-photo-wrap"><img class="cff-player-photo" loading="lazy" decoding="async" src="${esc(photo(p))}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='silhueta.webp'"><img class="cff-player-team-mini" src="${esc(logo)}" alt="" onerror="this.onerror=null;this.src='escudo.webp'"></div><div class="cff-player-info"><h3>${esc(p.name)}</h3><span class="cff-player-role">${esc(role(p))} • ${esc(r.rosterStatus||'Elenco')}</span><span class="cff-player-realname">${esc(r.fullName||'Nome completo não informado')}${r.state?` • ${esc(r.state)}`:''}</span><div class="cff-player-tags">${tags(p)}</div></div><div class="cff-player-stats"><div class="cff-player-stat"><small>Abates</small><strong>${format(s.kills)}</strong></div><div class="cff-player-stat"><small>Dano</small><strong>${format(s.damage)}</strong></div><div class="cff-player-stat"><small>Quedas</small><strong>${format(s.matches)}</strong></div><div class="cff-player-stat"><small>Média</small><strong>${avg}</strong></div></div></a>`}function render(team,data,stats,stages){const players=Object.values(data?.players||{}).sort((a,b)=>Number(b.currentRoster?.starter)-Number(a.currentRoster?.starter)||Number(b.currentRoster?.captain)-Number(a.currentRoster?.captain)||String(a.name).localeCompare(String(b.name),'pt-BR'));const logo=team.logo||'escudo.webp',row=teamRow(stages,team.name);const totals=players.reduce((a,p)=>{const s=playerStats(p,stats?.players);a.kills+=num(s.kills);a.damage+=num(s.damage);a.matches=Math.max(a.matches,num(s.matches));return a},{kills:0,damage:0,matches:0});document.title=`${team.name} | Central Free Fire`;root.innerHTML=`<section class="cff-team-hero"><img class="cff-team-logo" src="${esc(logo)}" alt="${esc(team.name)}" onerror="this.onerror=null;this.src='escudo.webp'"><div><span class="cff-team-kicker">FFWS BRASIL 2026 SPLIT 2</span><h1>${esc(team.name)}</h1><p>${esc(team.abbreviation||team.name)} • ${players.length} jogadores cadastrados</p></div><span class="cff-team-country">Brasil</span></section><section class="cff-team-stats"><div class="cff-team-stat"><small>Pontos na S2</small><strong>${format(row.points??row.pontos)}</strong></div><div class="cff-team-stat"><small>Abates na S2</small><strong>${format(row.kills??row.abates??totals.kills)}</strong></div><div class="cff-team-stat"><small>Booyahs</small><strong>${format(row.booyahs??row.booyah)}</strong></div><div class="cff-team-stat"><small>Quedas</small><strong>${format(row.matches??row.quedas??totals.matches)}</strong></div></section><section class="cff-team-section"><div class="cff-team-section-head"><div><h2>Elenco atual</h2><p>Fotos, funções e estatísticas da temporada atual.</p></div><span class="cff-team-badge">${players.filter(p=>p.currentRoster?.starter!==false).length} titulares</span></div><div class="cff-team-roster">${players.map(p=>card(p,stats?.players,logo)).join('')}</div><div class="cff-team-note">Esta página carrega apenas o arquivo da equipe e as estatísticas da FFWS BR 2026 S2. Os módulos pesados da home, EWC, LAFF e temporadas históricas não são baixados aqui.</div></section>`}function fail(message){root.innerHTML=`<section class="cff-team-error"><div><h1>Equipe não encontrada</h1><p>${esc(message||'Não foi possível carregar este perfil.')}</p><a href="index.html#ffws-br-s2-equipes">Voltar para as equipes</a></div></section>`}async function init(){try{const query=new URLSearchParams(location.search).get('time')||new URLSearchParams(location.search).get('id')||'';const teamsData=await json(`ffws-br-2026-s2/teams.json?v=${V}`),team=findTeam(teamsData.teams||[],query);if(!team)throw new Error('O nome informado não pertence aos 14 times da temporada atual.');const teamSlug=aliases[norm(team.name)]||slug(team.name);const [,data,stats,stages]=await Promise.all([window.cffLoadPlayerPhotoMap?.().catch(()=>null),json(`player-data/s2/${teamSlug}.json?v=${V}`),json(`ffws-br-2026-s2/player-stats.json?v=${V}`).catch(()=>({players:{}})),json(`ffws-br-2026-s2/stages.json?v=${V}`).catch(()=>({}))]);render(team,data,stats,stages)}catch(e){fail(e.message)}}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init()})();